function dupOf(c,d){const n=x=>String(x||'').trim().toLowerCase();if(c==='leads'){const x=S.leads.find(l=>n(l.name)===n(d.name)&&n(l.city)===n(d.city));return x?'A prospect named "'+x.name+'"'+(x.city?' in '+x.city:'')+' already exists. Edit that one, or change the name or city.':''}if(c==='projects'){const x=S.projects.find(p=>n(p.name)===n(d.name)&&(p.lead||'')===(d.lead||''));return x?'A project named "'+x.name+'" for this prospect already exists. Edit it instead.':''}if(c==='kb'){const x=S.kb.find(k=>n(k.title)===n(d.title)&&n(k.body)===n(d.body));return x?'This exact note is already saved.':''}if(c==='tasks'){const x=S.tasks.find(t=>t.status!=='Done'&&n(t.title)===n(d.title)&&(t.due||'')===(d.due||''));return x?'An open task with this title and due date already exists. Edit it, or change the title or date.':''}return ''}
const bkNote=()=>{const n=S.tasks.length+S.leads.length+S.projects.length+S.kb.length+S.proposals.length;if(!n)return '';const d=S.bk?Math.floor((Date.now()-new Date(S.bk))/864e5):null;return d===null?'<p><span class="tag warn">Backup</span> You have not exported a backup yet. Settings has Export JSON.</p>':d>=7?'<p><span class="tag warn">Backup</span> Last export started '+d+' days ago.</p>':''};
function pstat(){const e=$('#pst');if(!e)return;if(!(navigator.storage&&navigator.storage.persisted)){e.textContent='This browser does not report persistent storage.';return}navigator.storage.persisted().then(v=>{e.textContent=v?'Granted. The browser will try not to clear your data.':'Not granted. The browser may clear data when space is low or after long inactivity.'}).catch(()=>{e.textContent='Could not check.'})}
function recoveryHtml(){const p=getSnap(),d=S.bk?Math.floor((Date.now()-new Date(S.bk))/864e5):null;return `<h2>Recovery and privacy</h2><div class=card><p><b>Backups</b><br><span class=mu>${S.bk?'Last export started '+esc(new Date(S.bk).toLocaleString())+(d>=0?' ('+d+' day(s) ago)':'')+'. JARVIS cannot confirm where the file went.':'You have not exported a backup yet.'} Use Export JSON and Import JSON above. Restoring shows a preview first.</span></p><p><b>Safety snapshot</b><br><span class=mu>${p?'Taken '+esc(new Date(p.t).toLocaleString())+': '+esc(p.reason)+'. Only the most recent one is kept.':'None yet. One is saved automatically before a restore, a reset, a bulk delete or a data format update.'}</span></p>${p?'<div class=row><button class="btn vb" data-a=undo>Restore the safety snapshot</button></div>':''}<p><b>Persistent storage</b><br><span class=mu id=pst>Checking...</span></p><div class=row><button class="btn vb" data-a=persist>Ask the browser to keep my data</button></div><ul class=mu><li>Data lives only in this browser on this device. Clearing website data, removing the Home Screen app or switching devices erases it unless you have a backup.</li><li>There is no login or password and nothing is encrypted. Anyone who can use this browser profile can read your data, and backup files are plain text.</li><li>There is no cloud backup or sync.</li><li>JARVIS has no API keys and never asks for passwords. Text that looks like a password, API key or card/ID number is refused in forms, commands and notes (a pattern check that can miss some; contact details only get the password and key check because they hold phone numbers). Data saved earlier and imported backups are not re-scanned, except Vault notes.</li></ul></div>`}
const isD=x=>/^[0-9]{4}-[0-9]{2}-[0-9]{2}$/.test(String(x||'')),dd=x=>Math.round((Date.parse(today())-Date.parse(x))/864e5);
function recs(){const T=today(),R=[],add=o=>R.push(o),relOf=t=>[t.lead&&nm('leads',t.lead)&&'Prospect: '+nm('leads',t.lead),t.proj&&nm('projects',t.proj)&&'Project: '+nm('projects',t.proj)].filter(Boolean).join('. ');
 S.tasks.filter(t=>t.status!=='Done'&&isD(t.due)).forEach(t=>{const d=dd(t.due),rel=relOf(t);
  if(d>0)add({k:'task:'+t.id+':'+t.due,pri:t.priority==='High'?'High':'Medium',o:100+d,title:'Overdue task: '+t.title,why:'Due '+t.due+', '+d+' day(s) overdue.',next:'Finish it, or move the due date if plans changed.',rel,act:['nav','tasks','Open tasks']});
  else if(d>=-3)add({k:'dl:'+t.id+':'+t.due,pri:d===0&&t.priority==='High'?'High':'Medium',o:50+d,title:(d===0?'Due today: ':'Due soon: ')+t.title,why:d===0?'Due today.':'Due in '+(-d)+' day(s) ('+t.due+').',next:'Make time for it before the deadline.',rel,act:['nav','tasks','Open tasks']})});
 S.leads.filter(active).forEach(l=>{const rel='Prospect: '+l.name+' ('+l.status+')';
  if(isD(l.next)){const d=dd(l.next);
   if(d>0)add({k:'fu:'+l.id+':'+l.next,pri:'High',o:90+d,title:'Follow up with '+l.name,why:'Follow-up was due '+l.next+' ('+d+' day(s) ago). Stage: '+l.status+'.',next:'Send a follow-up message (a draft is ready below), then log it.',rel,task:{title:'Follow up with '+l.name,due:T,lead:l.id,priority:'High'},act:['fufocus',l.id,'View draft']});
   else if(d>=-3)add({k:'soon:'+l.id+':'+l.next,pri:'Medium',o:40+d,title:'Follow-up coming up: '+l.name,why:(d===0?'Due today.':'Due in '+(-d)+' day(s).')+' Stage: '+l.status+'.',next:'Prepare your follow-up.',rel,task:{title:'Follow up with '+l.name,due:l.next,lead:l.id,priority:'Medium'},act:['fufocus',l.id,'View draft']})}
  else if(['Contacted','Replied','Interested'].includes(l.status))add({k:'att:'+l.id+':'+l.status,pri:l.status==='Contacted'?'Medium':'High',o:30,title:'Set a follow-up for '+l.name,why:'Stage is '+l.status+' but no follow-up date is saved.',next:'Pick a follow-up date so this prospect is not forgotten.',rel,act:['edit',l.id,'Edit prospect','leads']});
  if(l.status==='New'&&isD(l.created)&&dd(l.created)>=7)add({k:'new:'+l.id,pri:'Low',o:5,title:'Research '+l.name,why:'Added '+dd(l.created)+' days ago and still at stage New.',next:'Research it, or mark it Lost if it is not worth pursuing.',rel,task:{title:'Research '+l.name,due:T,lead:l.id,priority:'Low'},act:['research',l.id,'Add research']})});
 S.projects.filter(p=>p.status!=='Live').forEach(p=>{const ot=S.tasks.filter(t=>t.proj===p.id&&t.status!=='Done'),rel='Project: '+p.name+' ('+p.status+')';
  if(!ot.length)add({k:'proj:'+p.id+':'+p.status+':none',pri:'Medium',o:20,title:'Project has no next step: '+p.name,why:'Status is '+p.status+' and no open task is linked, so progress is not tracked.',next:'Add the next step as a task.',rel,task:{title:'Next step for '+p.name,due:dt(1),proj:p.id,lead:p.lead||'',priority:'Medium'},act:['nav','lab','Open Website Lab']});
  else add({k:'proj:'+p.id+':'+p.status+':open',pri:p.status==='Review'?'High':'Medium',o:20+ot.length,title:'Project in progress: '+p.name,why:ot.length+' open task(s) linked. Status: '+p.status+'.',next:'Finish: '+ot.slice(0,2).map(t=>t.title).join('; '),rel,act:['nav','tasks','Open tasks']});
  if(p.status==='Review'&&!okUrl(p.url))add({k:'purl:'+p.id,pri:'Low',o:3,title:'No preview link saved: '+p.name,why:'The project is in Review but has no preview URL.',next:'Add the preview URL once the demo is hosted.',rel,act:['edit',p.id,'Edit project','projects']})});
 S.proposals.filter(p=>p.status==='Sent by you'&&isD(p.statusOn)&&dd(p.statusOn)>=5).forEach(p=>add({k:'prop:'+p.id+':'+p.statusOn,pri:'Medium',o:25,title:'No answer on proposal: '+p.title,why:'Marked as sent by you on '+p.statusOn+' ('+dd(p.statusOn)+' days ago). No outcome is recorded.',next:'Follow up, then mark the proposal accepted or declined.',rel:nm('leads',p.lead)?'Prospect: '+nm('leads',p.lead):'',task:{title:'Follow up on '+p.title,due:T,lead:p.lead||'',priority:'Medium'},act:['nav','flows','Open proposals']}));
 const goals=bz('goals').split(/[\n;]+/).map(x=>x.trim()).filter(x=>x.length>3).slice(0,3),hay=[...S.tasks.filter(t=>t.status!=='Done').map(t=>t.title+' '+(t.notes||'')),...S.brain.map(b=>b.title),...S.projects.map(p=>p.name),...S.cmds.map(x=>x.text)].join(' ').toLowerCase();
 if(!goals.length)add({k:'goal:none',pri:'Low',o:1,title:'No sales goals saved',why:'The business profile has no sales goals, so progress cannot be measured.',next:'Add your goals in the business profile.',act:['editbiz','','Edit business profile']});
 goals.forEach(g=>{const w=[...new Set(g.toLowerCase().match(/[a-z0-9]{4,}/g)||[])];if(!w.some(x=>hay.includes(x)))add({k:'goal:'+fnv(g),pri:'High',o:60,title:'No action plan for goal: '+g.slice(0,60),why:'No open task, saved plan, project or command mentions this goal. This is a keyword match, so differently worded work may be missed.',next:'Make a plan and turn its steps into tasks.',task:{title:'Plan how to reach: '+g.slice(0,80),due:dt(1),priority:'High'},act:['goalplan',fnv(g),'Make a plan'],goal:g})});
 return R.sort((a,b)=>PW[a.pri]-PW[b.pri]||b.o-a.o)}
const recNote=()=>{const o=recs().filter(r=>!S.rs.some(x=>x.k===r.k));return o.length?'<p><b>Recommendations:</b> '+o.length+' waiting ('+o.filter(r=>r.pri==='High').length+' high priority). <button class="btn sm vb" data-a=todayopen>Open</button></p>':''};
const recCard=r=>{const has=r.task&&S.tasks.some(t=>t.status!=='Done'&&String(t.title).toLowerCase()===r.task.title.toLowerCase());return `<div class=card><div class=row><b class=grow>${esc(r.title)}</b><span class="tag ${r.pri==='High'?'bad':r.pri==='Medium'?'warn':''}">${r.pri}</span></div><div class=mu><b>Why:</b> ${esc(r.why)}</div><div><b>Next:</b> ${esc(r.next)}</div>${r.rel?`<div class=mu>Related: ${esc(r.rel)}</div>`:''}<div class=row>${r.act?`<button class="btn sm vb" data-a=${r.act[0]} data-id="${esc(r.act[1])}"${r.act[3]?' data-c='+r.act[3]:''}>${esc(r.act[2])}</button>`:''}${r.task?(has?'<span class="tag ok">Task exists</span>':`<button class="btn sm pri vb" data-a=rectask data-k="${esc(r.k)}">Create task</button>`):''}<button class="btn sm vb" data-a=recst data-k="${esc(r.k)}" data-s=done>Mark done</button><button class="btn sm vb" data-a=recst data-k="${esc(r.k)}" data-s=dismissed>Dismiss</button></div></div>`};
function refName(ref){const [k,id]=String(ref||'').split(':');return k==='task'?'Task: '+((S.tasks.find(x=>x.id===id)||{}).title||'removed'):k==='lead'?'Prospect: '+(nm('leads',id)||'removed'):k==='proj'?'Project: '+(nm('projects',id)||'removed'):''}
function dayItems(){const T=today(),it=[],push=(text,kind,ref)=>{if(it.length<8)it.push({id:uid(),text,kind,ref,done:false})},opn=S.tasks.filter(t=>t.status!=='Done');
 opn.filter(t=>isD(t.due)&&t.due<T).sort((a,b)=>a.due<b.due?-1:1).slice(0,3).forEach(t=>push('Finish overdue task: '+t.title+' (due '+t.due+')','task','task:'+t.id));
 opn.filter(t=>t.due===T).forEach(t=>push('Do today: '+t.title,'task','task:'+t.id));
 S.leads.filter(l=>active(l)&&isD(l.next)&&l.next<=T).slice(0,3).forEach(l=>push('Follow up with '+l.name+' (due '+l.next+')','followup','lead:'+l.id));
 S.projects.filter(p=>['Building','Review'].includes(p.status)).slice(0,2).forEach(p=>push('Move project forward: '+p.name+' ('+p.status+')','project','proj:'+p.id));
 opn.filter(t=>isD(t.due)&&dd(t.due)<0&&dd(t.due)>=-2).slice(0,2).forEach(t=>push('Prepare for '+t.due+': '+t.title,'task','task:'+t.id));return it}
function dayHtml(){const d=S.day,T=today();return '<h2>Daily plan</h2>'+(d&&d.date===T?`<div class=card><div class=row><b class=grow>Plan for ${esc(d.date)}</b><span class="tag ${d.saved?'ok':'warn'}">${d.saved?'Saved':'Draft, not saved yet'}</span></div><div class=mu>${d.saved?'Ticking an item only updates this checklist. Manage the underlying tasks in Tasks.':'Review and edit the items, then tap Save plan.'}</div>${d.items.length?d.items.map((x,i)=>`<div style="margin:14px 0"><label style="display:flex;gap:10px;align-items:flex-start;color:var(--tx)"><input type=checkbox aria-label="Done" data-a=dayck data-id="${esc(x.id)}"${x.done?' checked':''}><span${x.done?' style="text-decoration:line-through;opacity:.6"':''}>${esc(x.text)}<div class=mu>${esc(refName(x.ref))}</div></span></label><div class=row><button class="btn sm vb" aria-label="Edit" data-a=dayedit data-id="${esc(x.id)}">Edit</button><button class="btn sm vb" aria-label="Move up" data-a=daymove data-d=-1 data-id="${esc(x.id)}"${i===0?' disabled':''}>&uarr;</button><button class="btn sm vb" aria-label="Move down" data-a=daymove data-d=1 data-id="${esc(x.id)}"${i===d.items.length-1?' disabled':''}>&darr;</button><button class="btn sm vb bad" aria-label="Remove" data-a=dayrm data-id="${esc(x.id)}">&times;</button></div></div>`).join(''):'<div class=empty>Nothing from your saved data is due. Add your own items.</div>'}<div class=row><button class="btn vb" data-a=dayadd>Add item</button>${d.saved?'':'<button class="btn pri vb" data-a=daysave>Save plan</button>'}<button class="btn vb" data-a=daycopy>Copy as text</button><button class="btn vb" data-a=daygen>Regenerate</button></div></div>`:`<div class=card><div class=mu>${d?'The last plan is from '+esc(d.date)+'. ':'No plan yet. '}A plan is built from your saved tasks, follow-ups and projects, and you can edit it before saving.</div><div class=row><button class="btn pri vb" data-a=daygen>Generate today's plan</button></div></div>`)}
const fuList=()=>S.leads.filter(l=>active(l)&&isD(l.next)&&dd(l.next)>=-7).map(l=>({l,d:dd(l.next)})).sort((a,b)=>b.d-a.d);
function fuDraft(l){const me=S.me||'a local web developer',pr=S.proposals.find(p=>p.lead===l.id&&p.status==='Sent by you'),last=isD(l.last)?' I last wrote to you on '+l.last+'.':'',body=pr?'I wanted to follow up on the proposal I shared for '+l.name+'.'+last+' Do you have any questions, or would you like me to adjust anything?':['Interested','Replied'].includes(l.status)?'Thank you for your interest in a website for '+l.name+'.'+last+' Shall I send over a short demo so you can see how it would look?':'I am following up on my earlier message about a website for '+l.name+(l.city?' in '+l.city:'')+'.'+last+' I can put together a short demo for you to look at. No pressure at all.';return (l.method==='Instagram'?'Hi! ':'Hi, ')+'this is '+me+'. '+body}
function fuHtml(){const L=fuList();return '<h2>Follow-ups</h2><p class=mu>Drafts use saved prospect details only. JARVIS cannot send them: you copy and send each message yourself.</p>'+(L.length?L.map(x=>{const l=x.l;return `<details id="fu-${esc(l.id)}" class=card${F.fu1===l.id?' open':''}><summary><b>${esc(l.name)}</b> <span class="tag ${x.d>0?'bad':'warn'}">${x.d>0?'Overdue by '+x.d+' day(s)':x.d===0?'Due today':'Due in '+(-x.d)+' day(s)'}</span> <span class=mu>${esc(l.status)}</span></summary><div class=mu>Follow-up date ${esc(l.next)}. Last contact: ${esc(l.last||'none recorded')}. ${esc(l.method||'')}${l.contact?': '+esc(l.contact):''}</div><div style="white-space:pre-wrap;margin:8px 0">${esc(fuDraft(l))}</div><div class=row><button class="btn sm pri vb" data-a=fucopy data-id="${esc(l.id)}">Copy draft</button><button class="btn sm vb" data-a=fulog data-id="${esc(l.id)}">I followed up</button><button class="btn sm vb" data-a=fudate data-id="${esc(l.id)}">Change date</button></div></details>`}).join(''):'<div class=empty>No follow-ups are overdue or due within the next 7 days.</div>')}
function todayHtml(){const all=recs(),open=all.filter(r=>!S.rs.some(x=>x.k===r.k));return `<h2>Priority engine</h2><p class=mu>Worked out from your saved data each time you open or refresh this screen. JARVIS does not watch anything in the background, and nothing is sent or created unless you tap a button.</p><div class=card><b>${open.length} recommendation(s)</b> <span class=mu>${open.filter(r=>r.pri==='High').length} high priority</span></div>`+(open.length?open.slice(0,F.rall?99:8).map(recCard).join('')+(open.length>8&&!F.rall?'<div class=row><button class="btn vb" data-a=recall>Show all '+open.length+'</button></div>':''):'<div class=empty>Nothing needs attention based on your saved data.</div>')+(S.rs.length?`<details class=card><summary class=mu>Handled recommendations (${S.rs.length})</summary>${S.rs.slice(0,30).map(r=>`<div class=row><div class=grow>${esc(r.n||r.k)}<div class=mu>${r.s==='done'?'Marked done':'Dismissed'} ${esc(String(r.t).slice(0,10))}</div></div><button class="btn sm vb" data-a=recback data-id="${esc(r.id)}">Restore</button></div>`).join('')}</details>`:'')+dayHtml()+fuHtml()}
