 mic:()=>{if(!SR){setVS('unsupported');return}if(REC){try{REC.stop()}catch(e){}return}if(!$('#cmd'))return;
  const r=new SR();REC=r;r.lang='en-IN';r.interimResults=true;r.continuous=false;let got=false;
  r.onstart=()=>setVS('listening','Listening. Speak now.');
  r.onresult=e=>{let t='';for(const x of e.results)t+=x[0].transcript;const c=$('#cmd');if(c){c.value=t.trim().slice(0,200);got=true}if(e.results[e.results.length-1].isFinal)setVS('processing','Finishing up.')};
  r.onspeechend=()=>setVS('processing','Finishing up.');
  r.onerror=e=>{const m={'not-allowed':'Microphone access was denied. Allow it in your browser or iPhone settings, or type instead.','service-not-allowed':'Speech recognition is not allowed in this browser. Type your command instead.','no-speech':'No speech was heard. Tap Speak and try again.','audio-capture':'No microphone was found.',network:'Speech recognition needs a network connection.',aborted:'Listening was stopped.'}[e.error];got=false;r.failed=true;setVS('ready',m||'Voice error: '+e.error)};
  r.onend=()=>{REC=null;if(r.failed)return;setVS('ready',got?'Review or edit the text, then tap Generate plan or Plan as workflow. Nothing has run.':'Nothing was recognised. Try again or type.')};
  try{r.start()}catch(e){REC=null;setVS('ready','Could not start voice input.')}},
