 copyreport:async()=>{const c=a=>S.leads.filter(l=>a.includes(l.status)).length;const t=`JARVIS report ${today()}: total leads ${S.leads.length}, contacted ${c(CON)}, replies ${c(REP)}, interested ${c(['Interested'])}, won ${c(['Won'])}, follow-ups due ${due().length}, overdue follow-ups ${S.leads.filter(l=>active(l)&&l.next&&l.next<today()).length}, website projects ${S.projects.length}, pending tasks ${S.tasks.filter(x=>x.status!=='Done').length}`;toast(await copy(t)?'Report copied':'Copy failed. Select the text and copy it manually.')},
