 lflows:id=>{const l=S.leads.find(x=>x.id===id);if(!l)return;open(`<h3>${esc(l.name)}</h3><p class=mu>Start a workflow for this prospect. You review the steps before anything runs.</p>`+[['brief','Demo brief'],['outreach','Outreach draft'],['followup','Schedule follow-up'],['proposal','Proposal draft']].map(x=>`<p><button class="btn vb" style="width:100%" data-a=tpl2 data-id="${esc(l.id)}" data-k="${x[0]}">${x[1]}</button></p>`).join('')+'<button class="btn vb" data-a=close>Close</button>')},
