function installCard(){const standalone=!!(navigator.standalone||(window.matchMedia&&matchMedia('(display-mode: standalone)').matches)),sw='serviceWorker' in navigator,ctl=sw&&navigator.serviceWorker.controller;
 return `<h2>Install and offline</h2><div class=card><p>Installed to Home Screen: <span class="tag ${standalone?'ok':'warn'}">${standalone?'Yes':'No, running in the browser'}</span> Offline support: <span class="tag ${ctl?'ok':'warn'}">${ctl?'Active':sw?'Not active yet, reload once while online':'Not available here'}</span></p><ul class=mu><li>To install: open this site in Safari, tap Share, then Add to Home Screen.</li><li>On iPhone, the Home Screen app and Safari keep separate storage. Export a backup from one and import it in the other.</li><li>Safari may clear site data for sites you have not opened for about a week. Home Screen apps are exempt from that rule as far as I know, but export backups regularly anyway.</li><li>There is no cloud sync. Your data stays on this device unless you export and import it.</li><li>Offline: the app files are cached after your first visit. Your business data stays in browser storage and is never cached by the service worker.</li><li>Voice input can be unreliable inside a Home Screen app on iPhone. If Speak fails there, open the site in Safari instead.</li><li>Workflows only run while the app is open. Nothing runs in the background.</li></ul></div>`}
