if('serviceWorker' in navigator&&/^https?:$/.test(location.protocol)){window.addEventListener('load',()=>{const had=!!navigator.serviceWorker.controller;navigator.serviceWorker.addEventListener('controllerchange',()=>{if(had)toast('A new version was installed. Close and reopen JARVIS to use it.')});navigator.serviceWorker.register('sw.js').then(r=>r.update()).catch(()=>{})})}

